#[derive(Debug)]
pub struct WorkerClient {
    claim_due: NativeRequestHandle<WorkerClaimDue>,
    expire: NativeRequestHandle<WorkerExpire>,
    process: NativeRequestHandle<WorkerProcess>,
    retry: NativeRequestHandle<WorkerRetry>,
}
impl WorkerClient {
    pub fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_dependencies(dependencies)
    }

    pub async fn claim_due(&self, request: ClaimDueRequest) -> Result<ClaimDueResponse, WorkerClaimDueInvocationError> {
        self.claim_due.invoke(CLAIM_DUE_OPERATION, request).await
            .map_err(WorkerClaimDueInvocationError::Runtime)?
            .map_err(WorkerClaimDueInvocationError::Domain)
    }

    pub async fn claim_due_with_context(&self, context: InvocationContext, request: ClaimDueRequest) -> Result<ClaimDueResponse, WorkerClaimDueInvocationError> {
        self.claim_due.invoke_with_context(CLAIM_DUE_OPERATION, context, request).await
            .map_err(WorkerClaimDueInvocationError::Runtime)?
            .map_err(WorkerClaimDueInvocationError::Domain)
    }

    pub async fn expire(&self, request: ExpireRequest) -> Result<ExpireResponse, WorkerExpireInvocationError> {
        self.expire.invoke(EXPIRE_OPERATION, request).await
            .map_err(WorkerExpireInvocationError::Runtime)?
            .map_err(WorkerExpireInvocationError::Domain)
    }

    pub async fn expire_with_context(&self, context: InvocationContext, request: ExpireRequest) -> Result<ExpireResponse, WorkerExpireInvocationError> {
        self.expire.invoke_with_context(EXPIRE_OPERATION, context, request).await
            .map_err(WorkerExpireInvocationError::Runtime)?
            .map_err(WorkerExpireInvocationError::Domain)
    }

    pub async fn process(&self, request: ProcessRequest) -> Result<ProcessResponse, WorkerProcessInvocationError> {
        self.process.invoke(PROCESS_OPERATION, request).await
            .map_err(WorkerProcessInvocationError::Runtime)?
            .map_err(WorkerProcessInvocationError::Domain)
    }

    pub async fn process_with_context(&self, context: InvocationContext, request: ProcessRequest) -> Result<ProcessResponse, WorkerProcessInvocationError> {
        self.process.invoke_with_context(PROCESS_OPERATION, context, request).await
            .map_err(WorkerProcessInvocationError::Runtime)?
            .map_err(WorkerProcessInvocationError::Domain)
    }

    pub async fn retry(&self, request: RetryRequest) -> Result<RetryResponse, WorkerRetryInvocationError> {
        self.retry.invoke(RETRY_OPERATION, request).await
            .map_err(WorkerRetryInvocationError::Runtime)?
            .map_err(WorkerRetryInvocationError::Domain)
    }

    pub async fn retry_with_context(&self, context: InvocationContext, request: RetryRequest) -> Result<RetryResponse, WorkerRetryInvocationError> {
        self.retry.invoke_with_context(RETRY_OPERATION, context, request).await
            .map_err(WorkerRetryInvocationError::Runtime)?
            .map_err(WorkerRetryInvocationError::Domain)
    }
}

impl CapabilityClient for WorkerClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            claim_due: dependencies.one::<WorkerClaimDue>()?,
            expire: dependencies.one::<WorkerExpire>()?,
            process: dependencies.one::<WorkerProcess>()?,
            retry: dependencies.one::<WorkerRetry>()?,
        })
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for WorkerClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    claim_due: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<WorkerClaimDue>()?,
                    expire: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<WorkerExpire>()?,
                    process: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<WorkerProcess>()?,
                    retry: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<WorkerRetry>()?,
                    },
                ))
            })
            .collect()
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum WorkerClaimDueInvocationError {
    Domain(ClaimDueError),
    Runtime(RuntimeFailure),
}
#[derive(Clone, Debug, PartialEq)]
pub enum WorkerExpireInvocationError {
    Domain(ExpireError),
    Runtime(RuntimeFailure),
}
#[derive(Clone, Debug, PartialEq)]
pub enum WorkerProcessInvocationError {
    Domain(ProcessError),
    Runtime(RuntimeFailure),
}
#[derive(Clone, Debug, PartialEq)]
pub enum WorkerRetryInvocationError {
    Domain(RetryError),
    Runtime(RuntimeFailure),
}
